(6459788, 959535, 23484, '<td valign="top">Very nice, very simple image. Great shot.</td>', 'Very nice, very simple image. Great shot.', '2011-07-03 13:33:07.000000', NULL, 1),
(6459793, 958606, 23484, '<td valign="top">The grain and composition are magnificent.</td>', 'The grain and composition are magnificent.', '2011-07-03 13:34:45.000000', NULL, 1),
(6459794, 956259, 23484, '<td valign="top">Beautiful image. Love the b&amp;w processing.</td>', 'Beautiful image. Love the b&w processing.', '2011-07-03 13:35:30.000000', NULL, 1),
(6459821, 959571, 76335, '<td valign="top">Very nice up close and personal. The thing''s snout is a face in itself. A face within a face. Excellent in black and white. Easily the best pig shot in this challenge (!).</td>', 'Very nice up close and personal. The thing''s snout is a face in itself. A face within a face. Excellent in black and white. Easily the best pig shot in this challenge (!).', '2011-07-03 13:48:39.000000', NULL, 1),
(6459827, 958606, 76335, '<td valign="top">The noise doesn''t suggest film grain to me, if that''s the "vintage" you''re after. It''s too crisp, too staticky. That said, I still think it''s a beautiful treatment in its own right.</td>', 'The noise doesn''t suggest film grain to me, if that''s the "vintage" you''re after. It''s too crisp, too staticky. That said, I still think it''s a beautiful treatment in its own right.', '2011-07-03 13:55:39.000000', NULL, 1),
(6459829, 959677, 76335, '<td valign="top">Surreal, minimalist, abstract. I like it. I want to quibble about the unlevel "horizon" -- but I like that you left it alone.</td>', 'Surreal, minimalist, abstract. I like it. I want to quibble about the unlevel "horizon" -- but I like that you left it alone.', '2011-07-03 13:56:56.000000', NULL, 1),
(6459831, 959447, 76335, '<td valign="top">Nice tones, subject isolation.</td>', 'Nice tones, subject isolation.', '2011-07-03 13:57:10.000000', NULL, 1),
(6459832, 958796, 76335, '<td valign="top">Beautifully posed and lit. I love how you brought out the texture in her skin.</td>', 'Beautifully posed and lit. I love how you brought out the texture in her skin.', '2011-07-03 13:57:41.000000', NULL, 1),
(6459835, 959770, 76335, '<td valign="top">Great feeling of anticipation and suspense here. Love the eyes.</td>', 'Great feeling of anticipation and suspense here. Love the eyes.', '2011-07-03 13:58:02.000000', NULL, 1),
(6459838, 959535, 76335, '<td valign="top">Something pleasingly pastoral about this. Great framing. Simple. Quiet. Not overworked. Great.</td>', 'Something pleasingly pastoral about this. Great framing. Simple. Quiet. Not overworked. Great.', '2011-07-03 14:00:57.000000', NULL, 1),
(6459866, 958473, 76335, '<td valign="top">Indeed. A nice candid. The high key is good. I think there might be too much headroom at the top. I might have framed it such that the crop fell just above lady left''s shoulder. This would also have put more emphasis on the child.</td>', 'Indeed. A nice candid. The high key is good. I think there might be too much headroom at the top. I might have framed it such that the crop fell just above lady left''s shoulder. This would also have put more emphasis on the child.', '2011-07-03 14:32:08.000000', NULL, 1),
(6459867, 959402, 76335, '<td valign="top">A little out of the box. I like the motion and liquid colors.</td>', 'A little out of the box. I like the motion and liquid colors.', '2011-07-03 14:32:39.000000', NULL, 1),
(6459871, 958190, 76335, '<td valign="top">I like this a lot. A wonderfully balanced composition set aquirk (a word I made up!) by the smeared refleciton of the tree.</td>', 'I like this a lot. A wonderfully balanced composition set aquirk (a word I made up!) by the smeared refleciton of the tree.', '2011-07-03 14:34:43.000000', NULL, 1),
