(6460781, 957073, 69325, '<td valign="top">wow, that bowl takes me back. we had that style when i was a kid. if they are still making it, it''s been around a long time</td>', 'wow, that bowl takes me back. we had that style when i was a kid. if they are still making it, it''s been around a long time', '2011-07-04 08:51:37.000000', NULL, 1),
(6460924, 959751, 76335, '<td valign="top">A fun moment and I love the dizzy look of the lady on the right. A vignette may work here, but this particular application doesn''t look right.</td>', 'A fun moment and I love the dizzy look of the lady on the right. A vignette may work here, but this particular application doesn''t look right.', '2011-07-04 12:07:18.000000', NULL, 1),
(6460925, 959683, 76335, '<td valign="top">Interesting (unexpected) point of view on this one.</td>', 'Interesting (unexpected) point of view on this one.', '2011-07-04 12:07:46.000000', NULL, 1),
(6460927, 959233, 76335, '<td valign="top">Not your everyday entry, for sure. The image is good. Tells a story. The title makes me think the situation isn''t dire (hope not), and the balloon lightens the mood.</td>', 'Not your everyday entry, for sure. The image is good. Tells a story. The title makes me think the situation isn''t dire (hope not), and the balloon lightens the mood.', '2011-07-04 12:09:56.000000', NULL, 1),
