(6461314, 959680, 76335, '<td valign="top">Mesmerizing. Hypnotic even. An out-of-the-box portrait which I like.</td>', 'Mesmerizing. Hypnotic even. An out-of-the-box portrait which I like.', '2011-07-04 20:15:58.000000', NULL, 1),
