(6461619, 958409, 10785, '<td valign="top">Very good colors. I think the foreground needs a little more light though.</td>', 'Very good colors. I think the foreground needs a little more light though.', '2011-07-05 08:52:58.000000', NULL, 1),
(6461620, 959499, 10785, '<td valign="top">Cool perspective. Awesome that you captured the dragonfly in flight on that angle. It''s color really stands out well from the background.</td>', 'Cool perspective. Awesome that you captured the dragonfly in flight on that angle. It''s color really stands out well from the background.', '2011-07-05 08:53:46.000000', NULL, 1),
(6461621, 959832, 10785, '<td valign="top">Good color. Nice silhouette. I think the sign coming out of his head is a distraction. It''s one of those minor details that needs to be watched out for. Changing the angle would have helped a lot.</td>', 'Good color. Nice silhouette. I think the sign coming out of his head is a distraction. It''s one of those minor details that needs to be watched out for. Changing the angle would have helped a lot.', '2011-07-05 08:55:02.000000', NULL, 1),
(6461625, 959640, 10785, '<td valign="top">I have been to Peru and am familiar with a scene such as this. Open air market in the middle of a small village. Women in their colorful clothing performing their trades. You did a good job with the harsh available light. Good use of perspective and leading lines.</td>', 'I have been to Peru and am familiar with a scene such as this. Open air market in the middle of a small village. Women in their colorful clothing performing their trades. You did a good job with the harsh available light. Good use of perspective and leading lines.', '2011-07-05 09:00:42.000000', NULL, 1),
(6461626, 957929, 10785, '<td valign="top">That is a very interesting sculpture. It kind of looks like a satellite dish peering into the heavens. Very unique! Good capture and good light on the subject.</td>', 'That is a very interesting sculpture. It kind of looks like a satellite dish peering into the heavens. Very unique! Good capture and good light on the subject.', '2011-07-05 09:03:45.000000', NULL, 1),
(6461627, 958939, 10785, '<td valign="top">Interesting dynamic with the gush of water. Watch out for that camera angle. It is slightly off on it''s rotation.</td>', 'Interesting dynamic with the gush of water. Watch out for that camera angle. It is slightly off on it''s rotation.', '2011-07-05 09:06:38.000000', NULL, 1),
(6461630, 958603, 10785, '<td valign="top">Her skin has a rather plastic look to it. It is clear and has some detail but still looks fake.</td>', 'Her skin has a rather plastic look to it. It is clear and has some detail but still looks fake.', '2011-07-05 09:10:32.000000', NULL, 1),
(6461636, 957343, 10785, '<td valign="top">Such a shame that you cut off the edges of the car, you chopped the shape. Get down lower too to get a better angle and really bring out that form. Good job on the selective desaturation and for not getting yourself in the reflections.</td>', 'Such a shame that you cut off the edges of the car, you chopped the shape. Get down lower too to get a better angle and really bring out that form. Good job on the selective desaturation and for not getting yourself in the reflections.', '2011-07-05 09:18:19.000000', NULL, 1),
(6461637, 957801, 10785, '<td valign="top">The blur really gives it that photo-impressionism quality.</td>', 'The blur really gives it that photo-impressionism quality.', '2011-07-05 09:19:58.000000', NULL, 1),
(6461639, 959436, 10785, '<td valign="top">Good use of the polarizing filter!!</td>', 'Good use of the polarizing filter!!', '2011-07-05 09:21:12.000000', NULL, 1),
