(6461729, 959493, 118154, '<td valign="top">Perfect model for the theme,really works well.</td>', 'Perfect model for the theme,really works well.', '2011-07-05 11:46:10.000000', NULL, 1),
(6461731, 959788, 118154, '<td valign="top">Angle makes this shot in my opinion.</td>', 'Angle makes this shot in my opinion.', '2011-07-05 11:47:04.000000', NULL, 1),
(6461744, 959680, 67258, '<td valign="top">With a more traditional and subdued catch light, this would have been a sure fire 10 from me.  You have captured such a delightful expression.  However, the ringlight flash catch-lights completely dominates the portrait, and my eyes constantly  draw back to them; they seem so much at odds with the soft delicateness of the photo.<br/> <br/>Back to edit typos, and to bump to 7.  I adore ebvery aspect of this photo - with the exception of those darn lights!!!  The ring-flash has given the most gorgeous, even, lighting to the photo - difficult one.</td>', 'With a more traditional and subdued catch light, this would have been a sure fire 10 from me.  You have captured such a delightful expression.  However, the ringlight flash catch-lights completely dominates the portrait, and my eyes constantly  draw back to them; they seem so much at odds with the soft delicateness of the photo. Back to edit typos, and to bump to 7.  I adore ebvery aspect of this photo - with the exception of those darn lights!!!  The ring-flash has given the most gorgeous, even, lighting to the photo - difficult one.', '2011-07-05 12:04:02.000000', NULL, 1),
(6461762, 959474, 76335, '<td valign="top">I like the honesty of this. The weathered hair and skin suggests that she''s no stranger to the sun. Yet it''s still a very glamorous and flattering portrait.</td>', 'I like the honesty of this. The weathered hair and skin suggests that she''s no stranger to the sun. Yet it''s still a very glamorous and flattering portrait.', '2011-07-05 12:39:50.000000', NULL, 1),
(6461763, 959461, 76335, '<td valign="top">Your main subject has his back to us and the surrounding action is relegated to the margins and further obscured by unnecesary vignetting. With all of this working against the image, it''s hard for the viewer to pick up the storyline.</td>', 'Your main subject has his back to us and the surrounding action is relegated to the margins and further obscured by unnecesary vignetting. With all of this working against the image, it''s hard for the viewer to pick up the storyline.', '2011-07-05 12:44:07.000000', NULL, 1),
(6461764, 957603, 76335, '<td valign="top">Interesting layers and shadows and reflections. Very characteristic of a half-conscious late night transit ride.</td>', 'Interesting layers and shadows and reflections. Very characteristic of a half-conscious late night transit ride.', '2011-07-05 12:45:31.000000', NULL, 1),
(6461766, 957014, 76335, '<td valign="top">Indeed it doesn''t. Wonderful textures and tones here. Great feeling of fragility.</td>', 'Indeed it doesn''t. Wonderful textures and tones here. Great feeling of fragility.', '2011-07-05 12:53:01.000000', NULL, 1),
(6461774, 958451, 76335, '<td valign="top">I have trouble with these. I appreciate that you engaged him, but all I see is another homeless person -- not an individual. A good start would have been to do away with that title and give us a name.</td>', 'I have trouble with these. I appreciate that you engaged him, but all I see is another homeless person -- not an individual. A good start would have been to do away with that title and give us a name.', '2011-07-05 13:03:21.000000', NULL, 1),
(6461777, 956435, 76335, '<td valign="top">Beautiful contrejour work. I love the sweeping vertical lines of trees that define this.</td>', 'Beautiful contrejour work. I love the sweeping vertical lines of trees that define this.', '2011-07-05 13:07:55.000000', NULL, 1),
(6461796, 959648, 76335, '<td valign="top">I love how the lady completes the composition -- separated from the torn backdrop in that she''s a living breathing person, yet, at the same time, inseperable from it. The diagonal line further comments on this dichotomy - a stroke of genius.</td>', 'I love how the lady completes the composition -- separated from the torn backdrop in that she''s a living breathing person, yet, at the same time, inseperable from it. The diagonal line further comments on this dichotomy - a stroke of genius.', '2011-07-05 13:39:23.000000', NULL, 1),
(6461798, 957225, 76335, '<td valign="top">Beautiful shadowplay, nice natural framing.</td>', 'Beautiful shadowplay, nice natural framing.', '2011-07-05 13:39:57.000000', NULL, 1),
(6461799, 959743, 76335, '<td valign="top">How can one dislike this?</td>', 'How can one dislike this?', '2011-07-05 13:40:24.000000', NULL, 1),
(6461800, 959097, 76335, '<td valign="top">I love how the action plays along the diagonal of the frame. Easy to read, hard to resist.</td>', 'I love how the action plays along the diagonal of the frame. Easy to read, hard to resist.', '2011-07-05 13:41:01.000000', NULL, 1),
