(6466522, 959839, 30982, '<td valign="top">A nice tribute to <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=29011" rel="nofollow" target="_blank">techo</a>''s entry from quite some time ago:  <a href="//www.dpchallenge.com/image.php?IMAGE_ID=354075" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/515/120/Copyrighted_Image_Reuse_Prohibited_354075.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/515/120/Copyrighted_Image_Reuse_Prohibited_354075.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/515/120/Copyrighted_Image_Reuse_Prohibited_354075.jpg"/></a></td>', 'A nice tribute to  techo''s entry from quite some time ago:  ', '2011-07-09 19:33:50.000000', NULL, 0),
